interface Figur {
  double getFlaeche();
  String getName();
}

class Rechteck implements Figur {
  protected double a;
  protected double b;
  private static int anzahl = 0;
  public Rechteck(double a, double b) {
    this.a = a;
    this.b = b;
    anzahl++;
  }
  public double getFlaeche() { return a * b; }
  public String getName() { return "Rechteck"; }
  public static int getAnzahl() { return anzahl; }
}

class Quadrat extends Rechteck {
  public Quadrat(double seite) { super(seite, seite); }
  public String getName() { return "Quadrat"; }
}

class Kreis implements Figur {
  private double r;
  public Kreis(double r) { this.r = r; }
  public double getFlaeche() { return 3.14159 * r * r; }
  public String getName() { return "Kreis"; }
}

