class Geometrie {
  public static void main(String[] s) {
    Punkt p1 = new Punkt(0, 10);
    Punkt p2 = new Punkt(5, 5);
    Punkt p3 = new Punkt(10, 5);
    Punkt p4 = new Punkt(15, 10);
    Punkt p5 = new Punkt(20, 0);

    Dreieck d1 = new Dreieck("D1", p1, p2, p3);
    Dreieck d2 = new Dreieck("D2", p3, p4, p5);

    System.out.println(d1.getName() + " xSumme=" + d1.xSumme());
    System.out.println(d2.getName() + " xSumme=" + d2.xSumme());
    System.out.println("gemeinsam: " + (d1.getEcke(2) == d2.getEcke(0)));
    System.out.println("Punkte: " + Punkt.getAnzahl());
  }
}

class Punkt {
  private int x;
  private int y;
  private static int anzahl = 0;
  public Punkt(int x, int y) {
    this.x = x;
    this.y = y;
    anzahl++;
  }
  public int getX() { return x; }
  public int getY() { return y; }
  public static int getAnzahl() { return anzahl; }
}

class Dreieck {
  private String name;
  private Punkt[] ecken = new Punkt[3];
  public Dreieck(String name, Punkt a, Punkt b, Punkt c) {
    this.name = name;
    ecken[0] = a;
    ecken[1] = b;
    ecken[2] = c;
  }
  public String getName() { return name; }
  public Punkt getEcke(int i) { return ecken[i]; }
  public int xSumme() {
    int summe = 0;
    for (int i = 0; i < ecken.length; i++) summe = summe + ecken[i].getX();
    return summe;
  }
}
